// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testRegression_property() public {
        address owner = address(this);
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        (bool ok,) = address(c).call{value: 1 ether}("");
        require(ok, "send failed");

        address nonOwner = address(0x1234);
        vm.deal(nonOwner, 1 wei);
        vm.prank(nonOwner);
        bytes memory data = "";
        bool success;
        try c.Command(address(0x5678), data) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success == false);
    }
}
